CREATE TABLE IF NOT EXISTS supermarkets(id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,address TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','active','suspended')),map_width INTEGER NOT NULL DEFAULT 1200,map_height INTEGER NOT NULL DEFAULT 760,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,supermarket_id TEXT REFERENCES supermarkets(id) ON DELETE CASCADE,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT,role TEXT NOT NULL CHECK(role IN('platform_owner','platform_staff','owner','manager','staff')),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','active','suspended')),email_verified INTEGER NOT NULL DEFAULT 0,last_login_at TIMESTAMP,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS auth_tokens(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,type TEXT NOT NULL,token_hash TEXT NOT NULL,expires_at TIMESTAMP NOT NULL,used_at TIMESTAMP,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS aisles(id TEXT PRIMARY KEY,supermarket_id TEXT NOT NULL REFERENCES supermarkets(id) ON DELETE CASCADE,code TEXT NOT NULL,name TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'aisle',x INTEGER NOT NULL,y INTEGER NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,UNIQUE(supermarket_id,code));
CREATE TABLE IF NOT EXISTS entrances(id TEXT PRIMARY KEY,supermarket_id TEXT NOT NULL REFERENCES supermarkets(id) ON DELETE CASCADE,name TEXT NOT NULL,x INTEGER NOT NULL,y INTEGER NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,supermarket_id TEXT NOT NULL REFERENCES supermarkets(id) ON DELETE CASCADE,aisle_id TEXT REFERENCES aisles(id) ON DELETE SET NULL,name TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'General',sku TEXT NOT NULL DEFAULT '',barcode TEXT NOT NULL DEFAULT '',price NUMERIC(12,2) NOT NULL DEFAULT 0,stock INTEGER NOT NULL DEFAULT 0,bay INTEGER NOT NULL DEFAULT 1,shelf TEXT NOT NULL DEFAULT 'Eye level',available INTEGER NOT NULL DEFAULT 1,x INTEGER NOT NULL DEFAULT 0,y INTEGER NOT NULL DEFAULT 0,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS invitations(id TEXT PRIMARY KEY,supermarket_id TEXT REFERENCES supermarkets(id) ON DELETE CASCADE,invited_by TEXT NOT NULL REFERENCES users(id),email TEXT NOT NULL,role TEXT NOT NULL,token_hash TEXT NOT NULL,expires_at TIMESTAMP NOT NULL,accepted_at TIMESTAMP,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY,supermarket_id TEXT REFERENCES supermarkets(id) ON DELETE CASCADE,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,metadata JSONB NOT NULL DEFAULT '{}',ip TEXT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS support_tickets(id TEXT PRIMARY KEY,supermarket_id TEXT REFERENCES supermarkets(id),user_id TEXT REFERENCES users(id),subject TEXT NOT NULL,description TEXT NOT NULL,priority TEXT NOT NULL DEFAULT 'normal',status TEXT NOT NULL DEFAULT 'open',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS product_search ON products(supermarket_id,LOWER(name));
CREATE INDEX IF NOT EXISTS audit_by_store ON audit_logs(supermarket_id,created_at);
CREATE TABLE IF NOT EXISTS session(sid VARCHAR NOT NULL,sess JSON NOT NULL,expire TIMESTAMP(6) NOT NULL,CONSTRAINT session_pkey PRIMARY KEY(sid));
CREATE INDEX IF NOT EXISTS session_expire_idx ON session(expire);
